mapper.update:
UPDATE schedule_availability_window
SET start_at = #{startAt}, end_at = #{endAt}, configured_capacity = #{capacity},
    version = version + 1, updated_at = #{now}
WHERE id = #{windowId} AND version = #{expectedVersion}
  AND status IN ('OPEN', 'SOLD_OUT')

UPDATE schedule_availability_window
SET status = 'CLOSED', version = version + 1, updated_at = #{now}
WHERE id = #{windowId} AND version = #{expectedVersion} AND status = 'OPEN'

UPDATE schedule_availability_window
SET status = 'OPEN', version = version + 1, updated_at = #{now}
WHERE id = #{windowId} AND version = #{expectedVersion} AND status = 'CLOSED'

UPDATE schedule_availability_window
SET status = #{nextStatus}, version = version + 1, updated_at = #{now}
WHERE id = #{windowId} AND status = #{expectedStatus}

UPDATE staff_availability_window
SET start_at = #{startAt}, end_at = #{endAt}, version = version + 1, updated_at = #{now}
WHERE id = #{windowId} AND version = #{expectedVersion} AND status = 'AVAILABLE'

UPDATE staff_availability_window
SET status = 'CLOSED', version = version + 1, updated_at = #{now}
WHERE id = #{windowId} AND version = #{expectedVersion} AND status = 'AVAILABLE'

UPDATE staff_availability_window
SET status = 'AVAILABLE', version = version + 1, updated_at = #{now}
WHERE id = #{windowId} AND version = #{expectedVersion} AND status = 'CLOSED'

UPDATE staff_capability_set
SET version = #{nextVersion}, updated_at = #{now}
WHERE staff_id = #{staffId} AND version = #{expectedVersion}
